@SpringBootTest
@Transactional
public class OrderServiceIntegrationTest {

    @Autowired
    private OrderRepository orderRepository;

    @Autowired
    private OrderService orderService;

    @Autowired
    private EntityManager entityManager;

    @Test
    public void testRollbackOnBusinessException() {
        OrderRequestDto request = new OrderRequestDto("SKU-123", 5);

        // Assert that a custom checked or unchecked business exception rolls back the transaction
        assertThrows(InsufficientInventoryException.class, () -> {
            orderService.processOrderWithExternalIo(request);
        });

        entityManager.flush();
        entityManager.clear();

        // Verify state is clean due to rollback
        List<Order> orders = orderRepository.findAll();
        assertTrue(orders.isEmpty(), "Transaction should have rolled back, leaving zero orders.");
    }
}
